st.push(root);
while (!st.empty()) {
    Node* cur = st.top();
    st.pop();
    for (std::size_t i = 0; i < cur->children.size(); ++i) {
        Node* c = cur->children[i];
        if (c == child) {
            return cur;
        }
        st.push(c);
    }
}
return nullptr;

